/* UI state is in memory only. Uploaded content is never sent or persisted. */
const E=ReconEngine,M=ReconModel,I=ReconIO,D=ReconDemo,$=s=>document.querySelector(s);
const model=M.fit(),evaluation=M.evaluate(model),state={files:{},data:null,result:null,filter:'review',excluded:new Set(),audit:[],pending:null};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const moneyFmt=(n,c='CNY')=>new Intl.NumberFormat('zh-CN',{style:'currency',currency:c}).format(n/100);
function message(text,error=false){$('#message').innerHTML=text?`<div class="msg ${error?'error':''}">${esc(text)}</div>`:'';}
function clearResult(){state.data=null;state.result=null;state.excluded.clear();state.audit=[];$('#results').hidden=true;$('#intro').hidden=false;$('#run').disabled=!(state.files.ledger&&state.files.bank);}
function log(action,detail){state.audit.push({time:new Date().toISOString(),action,detail});}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view],.view').forEach(el=>el.classList.remove('selected','active'));b.classList.add('selected');$('#'+b.dataset.view).classList.add('active');});
const detect=(headers,aliases)=>headers.findIndex(h=>aliases.some(a=>String(h).trim().toLowerCase()===a));
function mapping(side){$('#'+side+'Options').hidden=false;$('#'+side+'Options').open=true;const f=state.files[side],rows=f.sheets[f.sheetIndex].rows,headers=rows[f.headerRow-1]||[],length=Math.max(headers.length,...rows.slice(0,10).map(r=>r.length));if(length>100)throw Error('最多支持 100 列');f.headers=Array.from({length},(_,i)=>String(headers[i]??'').trim()||`未命名列 ${i+1}`);
const fields=[['date','日期',['日期','交易日期','记账日期','date','transaction date']],['description','摘要',['摘要','交易摘要','用途','description','memo','summary']],['amount','金额',['金额','收支金额','交易金额','amount']],['income','收入',['收入','收入金额','收款','income','credit']],['expense','支出',['支出','支出金额','付款','expense','debit']],['reference','交易编号（可不选）',['交易编号','流水号','参考号','reference','ref','transaction id']],['currency','币种（可不选）',['币种','currency']]];
if(!f.map){f.map={mode:'signed',defaultCurrency:'CNY',reverse:false};fields.forEach(([name,,aliases])=>f.map[name]=detect(f.headers,aliases));if(f.map.amount<0&&f.map.income>=0&&f.map.expense>=0)f.map.mode='split';}
const select=(name,label,options,value)=>`<label>${label}<select data-map="${name}" data-side="${side}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
const cols=[[-1,'请选择 / 不使用'],...f.headers.map((h,i)=>[i,h])];$('#'+side+'Mapping').innerHTML=`<div class="mapgrid">${select('sheet','工作表',f.sheets.map((s,i)=>[i,s.name]),f.sheetIndex)}<label>标题所在行<input data-map="header" data-side="${side}" type="number" min="1" max="20" value="${f.headerRow}"></label>${select('mode','金额结构',[['signed','单列：收入正，支出负'],['split','分列：收入与支出']],f.map.mode)}${select('defaultCurrency','未选择币种列时',['CNY','USD','EUR','GBP','HKD'].map(x=>[x,x]),f.map.defaultCurrency)}${fields.filter(([name])=>f.map.mode==='signed'?!['income','expense'].includes(name):name!=='amount').map(([name,label])=>select(name,label,cols,f.map[name])).join('')}</div><label class="small"><input type="checkbox" data-map="reverse" data-side="${side}" ${f.map.reverse?'checked':''}> 反转金额正负号（仅当源表方向相反时）</label><div class="preview">${esc(f.headers.join(' · '))}<br>${esc((rows[f.headerRow]||[]).join(' · '))}</div>`;}
document.addEventListener('change',e=>{const el=e.target;if(!el.dataset.map)return;const side=el.dataset.side,f=state.files[side],key=el.dataset.map;try{if(key==='sheet'){f.sheetIndex=Number(el.value);f.map=null;mapping(side);}else if(key==='header'){const n=Number(el.value);if(!Number.isInteger(n)||n<1||n>20)throw Error('标题行须为 1–20 的整数');f.headerRow=n;f.map=null;mapping(side);}else if(key==='reverse')f.map.reverse=el.checked;else if(key==='mode'){f.map.mode=el.value;mapping(side);}else if(key==='defaultCurrency')f.map.defaultCurrency=el.value;else f.map[key]=Number(el.value);clearResult();message('列设置已更新，请重新对账。');}catch(err){message(err.message,true);}});
['ledger','bank'].forEach(side=>$('#'+side+'File').onchange=async e=>{const file=e.target.files[0];if(!file)return;const input=e.target;input.disabled=true;message('正在读取 '+file.name+'…');try{const data=await I.readFile(file);state.files[side]={...data,sheetIndex:0,headerRow:1,name:file.name,map:null};$('#'+side+'Name').textContent=file.name;mapping(side);clearResult();message('文件已读取，请确认列对应及金额方向。');}catch(err){message(err.message,true);}finally{input.disabled=false;}});
['days','tolerance'].forEach(id=>$('#'+id).onchange=()=>{if(state.result){clearResult();message('匹配设置已修改，请重新对账。');}});
function validateMap(f){const m=f.map,required=['date','description',...(m.mode==='split'?['income','expense']:['amount'])];if(required.some(k=>m[k]<0||!Number.isInteger(m[k])))throw Error('请选择日期、摘要和金额列');const all=required.map(k=>m[k]).concat(['reference','currency'].map(k=>m[k]).filter(v=>v>=0));if(new Set(all).size!==all.length)throw Error('不同字段不能选择同一列');}
function perform(){try{['ledger','bank'].forEach(s=>validateMap(state.files[s]));const days=Number($('#days').value),tolerance=E.money($('#tolerance').value);const parsed={};for(const [side,code] of [['ledger','L'],['bank','B']]){const f=state.files[side];parsed[side]=E.normalize(f.sheets[f.sheetIndex].rows.slice(f.headerRow),f.map,code,{date1904:f.date1904,headerRow:f.headerRow});if(parsed[side].valid.length>2000)throw Error('每张表最多 2000 条记录');}const result=E.reconcile(parsed.ledger.valid,parsed.bank.valid,model,{maxDays:days,diffCents:tolerance});E.totals(parsed.ledger.valid);E.totals(parsed.bank.valid);state.data={ledger:parsed.ledger.valid,bank:parsed.bank.valid,errors:[...parsed.ledger.errors,...parsed.bank.errors]};state.result=result;state.excluded.clear();state.audit=[];log('开始对账',`账本 ${state.data.ledger.length} 笔，流水 ${state.data.bank.length} 笔；日期窗口 ${days} 天，差异候选上限 ${tolerance/100}`);$('#results').hidden=false;$('#intro').hidden=true;$('#ledgerOptions').open=false;$('#bankOptions').open=false;state.filter=state.data.errors.length?'issues':'review';render();message(state.data.errors.length?`${state.data.errors.length} 行存在数据问题，已排除。控制总额仅包含有效记录。`:`首轮对账完成：${result.matches.length} 对明确匹配，其余请复核。`,!!state.data.errors.length);}catch(err){message(err.message,true);}}
$('#run').onclick=()=>{if(state.result)clearResult();$('#run').disabled=true;setTimeout(()=>{perform();$('#run').disabled=false;},20);};
$('#demo').onclick=()=>{for(const side of ['ledger','bank']){state.files[side]={name:side==='ledger'?'虚构公司账本.xlsx':'虚构银行流水.xlsx',sheets:[{name:'Transactions',rows:[D.headers,...D[side]]}],date1904:false,sheetIndex:0,headerRow:1,map:null};$('#'+side+'Name').textContent=state.files[side].name;$('#'+side+'File').value='';mapping(side);}clearResult();$('#days').value=3;$('#tolerance').value=100;state.filter='review';perform();document.querySelector('[data-view="workspace"]').click();};
const key=c=>c.ledgerId+'|'+c.bankId;
function available(){const usedL=new Set(state.result.matches.map(m=>m.ledgerId)),usedB=new Set(state.result.matches.map(m=>m.bankId));return state.result.candidates.filter(c=>!usedL.has(c.ledgerId)&&!usedB.has(c.bankId)&&!state.excluded.has(key(c)));}
const stat=(label,value,foot,cls='')=>`<div class="stat ${cls}"><label>${label}</label><strong>${value}</strong><small>${foot}</small></div>`;
function transaction(r,label){return `<div class="transaction"><small>${label} · 源行 ${r.sourceRow} · ${esc(r.dateText)}</small><strong>${esc(moneyFmt(r.amount,r.currency))}</strong><p>${esc(r.description)}</p><small>编号：${esc(r.ref||'未提供')}</small></div>`;}
function render(){const d=state.data,r=state.result,candidates=available(),usedL=new Set(r.matches.map(m=>m.ledgerId)),usedB=new Set(r.matches.map(m=>m.bankId)),ul=d.ledger.filter(x=>!usedL.has(x.id)),ub=d.bank.filter(x=>!usedB.has(x.id)),lm=new Map(d.ledger.map(x=>[x.id,x])),bm=new Map(d.bank.map(x=>[x.id,x]));const auto=r.matches.filter(x=>x.kind==='auto').length,manual=r.matches.length-auto;$('#stats').innerHTML=stat('有效记录',d.ledger.length+d.bank.length,`账本 ${d.ledger.length} · 流水 ${d.bank.length}`)+stat('已匹配',r.matches.length,`自动 ${auto} · 人工 ${manual}`,'green')+stat('待复核账本',new Set(candidates.map(c=>c.ledgerId)).size,`${candidates.length} 个可选关联`,'amber')+stat('未匹配记录',ul.length+ub.length,`账本 ${ul.length} · 流水 ${ub.length}`);
const lt=E.totals(d.ledger),bt=E.totals(d.bank),currencies=[...new Set([...Object.keys(lt),...Object.keys(bt)])];$('#balances').innerHTML=`<table><thead><tr><th>币种</th><th>账本净额</th><th>流水净额</th><th>差额</th></tr></thead><tbody>${currencies.map(c=>`<tr><td>${c}</td><td>${esc(moneyFmt(lt[c]||0,c))}</td><td>${esc(moneyFmt(bt[c]||0,c))}</td><td>${esc(moneyFmt((bt[c]||0)-(lt[c]||0),c))}</td></tr>`).join('')}</tbody></table>`;
$('#reviewCount').textContent=new Set(candidates.map(c=>c.ledgerId)).size;$('#matchedCount').textContent=r.matches.length;$('#unmatchedCount').textContent=ul.length+ub.length;$('#issueCount').textContent=d.errors.length+r.duplicateLedger.length+r.duplicateBank.length;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===state.filter));let html='';
if(state.filter==='review')html=candidates.map(c=>{const a=lm.get(c.ledgerId),b=bm.get(c.bankId),warn=c.diff||c.conflict;return `<article class="matchcard"><div class="matchtop"><span class="badge ${warn?'warn':''}">${warn?'差异 / 冲突待核查':'候选关联'}</span><span class="reason">排序分数 ${c.score.toFixed(2)} · 不代表正确概率</span></div><div class="pair">${transaction(a,'账本')}<div class="arrow">⇄</div>${transaction(b,'流水')}</div><div class="matchactions"><span class="reason">${esc(c.reasons.join(' · '))}</span><button data-exclude="${esc(key(c))}">排除此候选</button><button class="primary" data-confirm="${esc(key(c))}">确认匹配</button></div></article>`;}).join('');
else if(state.filter==='matched')html=r.matches.map(m=>{const a=lm.get(m.ledgerId),b=bm.get(m.bankId);return `<article class="matchcard"><div class="matchtop"><span class="badge good">${m.kind==='auto'?'自动匹配':'人工确认'}</span><button data-undo="${esc(key(m))}">撤销匹配</button></div><div class="pair">${transaction(a,'账本')}<div class="arrow">⇄</div>${transaction(b,'流水')}</div><div class="reason">${esc(m.reason)}${b.amount!==a.amount?' · 仍有金额差异 '+esc(moneyFmt(b.amount-a.amount,a.currency)):''}</div></article>`;}).join('');
else if(state.filter==='unmatched'){const row=(x,type)=>`<tr><td>${type}</td><td>${x.sourceRow}</td><td>${x.dateText}</td><td>${esc(moneyFmt(x.amount,x.currency))}</td><td>${esc(x.description)}</td><td>${esc(x.ref)}</td></tr>`;html=ul.length+ub.length?`<div class="card tablewrap"><p class="small">包含仍有候选但尚未确认的记录。</p><table class="dataTable"><thead><tr><th>来源</th><th>源行</th><th>日期</th><th>金额</th><th>摘要</th><th>编号</th></tr></thead><tbody>${ul.map(x=>row(x,'账本')).join('')+ub.map(x=>row(x,'流水')).join('')}</tbody></table></div>`:'';}
else {html=d.errors.map(x=>`<div class="problem">${x.side==='L'?'账本':'流水'}源行 ${x.sourceRow}：${esc(x.message)}<br><small>${esc(x.raw.join(' · '))}</small></div>`).join('');const duplicates=[...r.duplicateLedger.map(id=>lm.get(id)),...r.duplicateBank.map(id=>bm.get(id))];html+=duplicates.map(x=>`<div class="problem">疑似重复：${x.side==='L'?'账本':'流水'}源行 ${x.sourceRow}，${esc(x.description)}，${esc(moneyFmt(x.amount,x.currency))}。保留原始记录，仅提示核查，不自动删除。</div>`).join('');}
$('#resultList').innerHTML=html||'<div class="empty">当前分类没有记录。</div>';$('#audit').innerHTML=`<details><summary>本次操作记录 (${state.audit.length})</summary>${state.audit.map(a=>`<p>${esc(new Date(a.time).toLocaleTimeString())} · ${esc(a.action)} · ${esc(a.detail)}</p>`).join('')}</details>`;}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;if(state.result)render();});
function accept(c){try{state.result.matches=E.confirm(state.result.matches,c);log('人工确认',key(c));render();message('已建立关联。可在“已匹配”中撤销；金额差异仍保留。');}catch(err){message(err.message,true);}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!state.result)return;if(b.dataset.confirm){const c=available().find(x=>key(x)===b.dataset.confirm);if(!c)return;const needsCheck=c.diff||c.conflict||state.result.duplicateLedger.includes(c.ledgerId)||state.result.duplicateBank.includes(c.bankId);if(needsCheck){state.pending=c;$('#confirmText').textContent=c.reasons.join('；');$('#confirmDialog').showModal();}else accept(c);}else if(b.dataset.exclude){state.excluded.add(b.dataset.exclude);log('排除候选',b.dataset.exclude);render();}else if(b.dataset.undo){const undone=state.result.matches.find(m=>key(m)===b.dataset.undo);if(undone&&!state.result.candidates.some(c=>key(c)===key(undone))){const a=state.data.ledger.find(x=>x.id===undone.ledgerId),bk=state.data.bank.find(x=>x.id===undone.bankId);state.result.candidates.push({...undone,score:1,textScore:model.score(a.description,bk.description),days:Math.abs(a.date-bk.date),reasons:['之前自动匹配，现已撤销，请重新复核'],conflict:false});}state.result.matches=state.result.matches.filter(m=>key(m)!==b.dataset.undo);state.excluded.delete(b.dataset.undo);log('撤销匹配',b.dataset.undo);render();}});
$('#cancelConfirm').onclick=()=>{state.pending=null;$('#confirmDialog').close();};$('#acceptConfirm').onclick=()=>{if(state.pending)accept(state.pending);state.pending=null;$('#confirmDialog').close();};
function download(content,name,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#export').onclick=()=>{if(!state.result)return;download(I.csv(E.exportRows(state.data.ledger,state.data.bank,state.result)),'对账报告.csv');if(state.data.errors.length)download(I.csv([['来源','源行','问题','原始数据'],...state.data.errors.map(x=>[x.side,x.sourceRow,x.message,x.raw.join(' | ')])]),'数据问题.csv');log('导出报告',`匹配 ${state.result.matches.length} 对`);render();message('报告已导出。待复核候选不会冒充已匹配；无效行另列数据问题。');};
$('#modelMetrics').innerHTML=stat('训练 / 测试',`${evaluation.trainSize} / ${evaluation.testSize}`,'合成文本对')+stat('测试准确率',(evaluation.accuracy*100).toFixed(1)+'%','阈值 0.5，仅文本模型')+stat('Precision',evaluation.precision.toFixed(3),'预测关联中的真关联占比')+stat('Recall',evaluation.recall.toFixed(3),'真实关联的识别比例');
$('#failures').innerHTML=evaluation.rows.filter(r=>r.expected!==r.predicted).map(r=>`<div class="failure">${esc(r.a)} ↔ ${esc(r.b)}<br><span class="reason">合成标注：${r.expected?'关联':'不关联'}；模型：${r.predicted?'关联':'不关联'}；分数 ${r.score.toFixed(2)}</span></div>`).join('');
$('#evalExport').onclick=()=>download(JSON.stringify(evaluation,null,2),'model-evaluation.json','application/json');
